  var _conv = $('a-subconv').value.trim();
  if (_conv && _conv.indexOf('http://') !== 0 && _conv.indexOf('https://') !== 0){ toast('订阅转换器地址必须以 http:// 或 https:// 开头', 'err'); $('a-subconv').focus(); return; }
